import React, { useEffect, useRef } from "react";
import { motion, useInView } from "framer-motion";
import { STATS } from "./Content";
import { Award, Users, Globe, Heart } from "lucide-react";

function Counter({ to, suffix, index }) {
  const [val, setVal] = React.useState(0);
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-50px" });

  useEffect(() => {
    if (isInView) {
      const duration = 1800;
      const start = performance.now();
      const tick = (now) => {
        const p = Math.min(1, (now - start) / duration);
        const eased = 1 - Math.pow(1 - p, 3);
        setVal(Math.round(to * eased));
        if (p < 1) requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
    }
  }, [isInView, to]);

  return (
    <motion.span ref={ref} className="serif block" style={{ fontSize: "clamp(36px, 5vw, 52px)", color: "#d4af37", fontWeight: 400 }} initial={{ opacity: 0, scale: 0.5 }} animate={isInView ? { opacity: 1, scale: 1 } : {}} transition={{ delay: index * 0.1, duration: 0.5 }}>
      {val.toLocaleString()}{suffix}
    </motion.span>
  );
}

export default function About() {
  const ref = useRef(null);
  const isInView = useInView(ref, { once: true, margin: "-50px" });

  return (
    <section id="about" className="section" style={{ background: "#fdf8ed" }}>
      <div className="container mx-auto">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 lg:gap-20 items-center">
          <motion.div initial={{ opacity: 0, x: -30 }} whileInView={{ opacity: 1, x: 0 }} viewport={{ once: true }} transition={{ duration: 0.7 }}>
            <div className="flex items-center gap-3 mb-6">
              <div className="w-10 h-px" style={{ background: "linear-gradient(90deg, transparent, #d4af37)" }} />
              <span className="section-overline">The Legacy</span>
            </div>
            <h2 className="section-title">A fabric house from Ludhiana, adorning India&apos;s grandest <span>celebrations</span>.</h2>
            <p className="section-subtitle mt-6">For over a decade, D SAJAWAT has been the quiet hand behind some of the country&apos;s most exquisite wedding venues. We source, finish and supply premium fabrics - drapes, covers, sashes, florals.</p>
            <p className="mt-6 text-base lg:text-lg" style={{ color: "rgba(26,8,10,0.7)", lineHeight: 1.8 }}>From a single roll to a banquet&apos;s worth - we deliver across India, on time, in finish.</p>

            <div className="grid grid-cols-2 gap-6 mt-10">
              {[{ icon: Award, title: "Premium Quality", desc: "Every roll inspected" }, { icon: Users, title: "350+ Decorators", desc: "Trust our products" }, { icon: Globe, title: "240+ Cities", desc: "Pan India reach" }, { icon: Heart, title: "12+ Years", desc: "Of excellence" }].map((item, i) => (
                <motion.div key={item.title} className="flex items-start gap-4" initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }} transition={{ delay: 0.2 + i * 0.1 }}>
                  <div className="w-12 h-12 rounded-xl flex items-center justify-center flex-shrink-0" style={{ background: "rgba(212,175,55,0.15)" }}><item.icon size={22} color="#d4af37" /></div>
                  <div><h4 className="font-semibold" style={{ color: "#1a080a" }}>{item.title}</h4><p className="text-sm" style={{ color: "rgba(26,8,10,0.6)" }}>{item.desc}</p></div>
                </motion.div>
              ))}
            </div>
          </motion.div>

          <motion.div ref={ref} className="stats-grid" initial={{ opacity: 0, x: 30 }} whileInView={{ opacity: 1, x: 0 }} viewport={{ once: true }} transition={{ duration: 0.7, delay: 0.2 }}>
            {STATS.map((stat, i) => (
              <motion.div key={stat.label} className="card text-center" initial={{ opacity: 0, y: 20 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true }} transition={{ delay: 0.3 + i * 0.1 }} whileHover={{ y: -6 }}>
                <Counter to={stat.value} suffix={stat.suffix} index={i} />
                <span className="section-overline mt-3 block">{stat.label}</span>
              </motion.div>
            ))}
          </motion.div>
        </div>
      </div>
    </section>
  );
}
